host.querySelectorAll('[data-trace-lot]').forEach(b=>b.onclick=()=>{stockDetailId=b.dataset.traceLot;stockEditingId=null;render();host.querySelector('#stock-detail-close')?.scrollIntoView({block:'nearest'});});
host.querySelectorAll('[data-close-lot]').forEach(b=>b.onclick=()=>{closeSelectedId=b.dataset.closeLot;render();host.querySelector('#close-form')?.scrollIntoView({block:'nearest'});});
host.querySelector('#close-cancel')?.addEventListener('click',()=>{closeSelectedId='';render()});
