if(host.querySelector('#history-lot'))host.querySelector('#history-lot').value=historyFilter;
function filterClose(){const q=(host.querySelector('#close-search')?.value||'').toLowerCase().trim(),st=host.querySelector('#close-filter')?.value||'';host.querySelectorAll('[data-close-row]').forEach(r=>r.hidden=!(r.dataset.closeRow.includes(q)&&(!st||r.dataset.closeStatus===st)));}
host.querySelector('#close-search')?.addEventListener('input',filterClose);host.querySelector('#close-filter')?.addEventListener('change',filterClose);
host.querySelector('#stock-edit-form')?.addEventListener('submit',saveStockEdit);
host.querySelector('#stock-edit-cancel')?.addEventListener('click',()=>{stockEditingId=null;render()});host.querySelector('#stock-detail-close')?.addEventListener('click',()=>{stockDetailId=null;render()});
