function openProductDialog(){const dialog=host?.querySelector('#psi-product-dialog');if(!dialog)return;dialog.hidden=false;document.body.classList.add('psi-product-modal-open');dialog.querySelector('h2').textContent=editingId?'Editar producto del catálogo':'Registrar nuevo producto';dialog.querySelector('[name="name"]')?.focus();}
function closeProductDialog(){const dialog=host?.querySelector('#psi-product-dialog');if(dialog)dialog.hidden=true;document.body.classList.remove('psi-product-modal-open');}
function enhanceProducts241(){
 if(!host)return;
 const panel=host.querySelector('.product-panel');if(!panel)return;
 if(tab==='catalog'){
  const form=host.querySelector('#product-form');if(form){
   const dlg=document.createElement('div');dlg.id='psi-product-dialog';dlg.className='psi-product-dialog';dlg.hidden=true;
   dlg.innerHTML='<div class="psi-product-shade"></div><div class="psi-product-window" role="dialog" aria-modal="true" aria-label="Expediente de producto"><header><div><small>LAB-PSI · CATÁLOGO MAESTRO</small><h2>Registrar nuevo producto</h2></div><button type="button" id="psi-product-x" aria-label="Cerrar">✕</button></header><div class="psi-product-dialog-body"></div></div>';
   dlg.querySelector('.psi-product-dialog-body').appendChild(form);panel.appendChild(dlg);
   dlg.querySelector('#psi-product-x').onclick=closeProductDialog;
   dlg.querySelector('.psi-product-shade').onclick=closeProductDialog;
   const toolbar=document.createElement('div');toolbar.className='psi-product-toolbar';toolbar.innerHTML='<div><strong>Catálogo maestro</strong><small>Consulte productos; abra el expediente únicamente para registrar o editar.</small></div><button type="button" id="psi-new-product">＋ Nuevo producto</button>';
   panel.querySelector('.product-list-head')?.before(toolbar);
   toolbar.querySelector('button').onclick=()=>{editingId=null;clearDraft();render();openProductDialog();};
   if(editingId)openProductDialog();
  }
 }
 // V1.0.243: formularios y expedientes en ventanas flotantes sin recrear formularios
 // ni sustituir sus manejadores originales de validación y guardado.
 const modalSpecs={
  receive:{selector:'#lot-form',title:'Recepción y evaluación de lote',button:'＋ Registrar recepción',subtitle:'Registre un lote con su documentación y evaluación.'},
  use:{selector:'#use-form',title:'Registrar consumo',button:'＋ Registrar movimiento',subtitle:'Consumos trazables de frascos abiertos.'}
 };
 const spec=modalSpecs[tab];
 if(spec){
  const form=panel.querySelector(spec.selector);
  if(form){
   const toolbar=document.createElement('div');toolbar.className='psi-product-toolbar psi-module-toolbar';
   toolbar.innerHTML=`<div><strong>${spec.title}</strong><small>${spec.subtitle}</small></div><button type="button" class="psi-open-module">${spec.button}</button>`;
   form.before(toolbar);
   const dlg=document.createElement('div');dlg.className='psi-product-dialog psi-module-dialog';dlg.hidden=true;
   dlg.innerHTML=`<div class="psi-product-shade"></div><div class="psi-product-window" role="dialog" aria-modal="true" aria-label="${spec.title}"><header><div><small>LAB-PSI · RECURSOS MICROBIOLÓGICOS</small><h2>${spec.title}</h2></div><button type="button" class="psi-module-close" aria-label="Cerrar ventana">✕</button></header><div class="psi-product-dialog-body"></div></div>`;
   dlg.querySelector('.psi-product-dialog-body').append(form);panel.append(dlg);
   const close=()=>{dlg.hidden=true;document.body.classList.remove('psi-product-modal-open');};
   toolbar.querySelector('button').onclick=()=>{dlg.hidden=false;document.body.classList.add('psi-product-modal-open');dlg.querySelector('input:not([type="hidden"]),select')?.focus();};
   dlg.querySelector('.psi-module-close').onclick=close;dlg.querySelector('.psi-product-shade').onclick=close;
  }
 }
 if(tab==='stock'||tab==='close'){
  const sections=[...panel.querySelectorAll('.product-subpanel')];
  const modalSection=sections.find(x=>x.querySelector('#lot-open-form,#stock-edit-form,#close-form') || (tab==='stock'&&x.querySelector('#stock-detail-close')));
  if(modalSection){
   const dlg=document.createElement('div');dlg.className='psi-product-dialog psi-module-dialog';
   dlg.innerHTML='<div class="psi-product-shade"></div><div class="psi-product-window" role="dialog" aria-modal="true" aria-label="Expediente del frasco"><header><div><small>LAB-PSI · TRAZABILIDAD DE LOTES</small><h2>Expediente del frasco</h2></div><button type="button" class="psi-module-close" aria-label="Cerrar ventana">✕</button></header><div class="psi-product-dialog-body"></div></div>';
   dlg.querySelector('.psi-product-window h2').textContent=modalSection.querySelector('h3')?.textContent||'Expediente del frasco';
   dlg.querySelector('.psi-product-dialog-body').append(modalSection);panel.append(dlg);
   document.body.classList.add('psi-product-modal-open');
   const close=()=>{document.body.classList.remove('psi-product-modal-open');openingLotId=null;stockEditingId=null;stockDetailId=null;closeSelectedId=null;render();};
   dlg.querySelector('.psi-module-close').onclick=close;dlg.querySelector('.psi-product-shade').onclick=close;
  }
 }
 // Paginación local de filas ya recibidas: no modifica Firestore ni el historial.
 const wrap=panel.querySelector('.product-table-wrap');const tbody=wrap?.querySelector('tbody');
 if(!tbody)return;
 const rows=[...tbody.querySelectorAll('tr')];if(!rows.length)return;
 const pager=document.createElement('div');pager.className='psi-product-pager';
 pager.innerHTML='<span class="psi-page-summary" aria-live="polite"></span><label>Mostrar <select class="psi-page-size"><option>10</option><option>25</option><option>50</option></select></label><button type="button" class="psi-page-prev">Anterior</button><span class="psi-page-number"></span><button type="button" class="psi-page-next">Siguiente</button>';
 wrap.after(pager);
 let page=0,size=10;
 const search=tab==='history'?null:panel.querySelector('#stock-search,#close-search,#product-search');
 const filterSelect=tab==='history'?null:panel.querySelector('#stock-status,#close-filter,#product-type-filter,#product-config-filter');
 let term='';
 if(tab==='history'){
  const searchBox=document.createElement('input');searchBox.type='search';searchBox.className='psi-history-search';searchBox.placeholder='Buscar movimiento, frasco, responsable o fecha';
  wrap.before(searchBox);searchBox.addEventListener('input',()=>{term=searchBox.value.toLocaleLowerCase().trim();page=0;refresh();});
 }
 function refresh(){
  const eligible=rows.filter(r=>{
   if(tab==='history')return !term||r.textContent.toLocaleLowerCase().includes(term);
   if(tab==='catalog'){const q=(panel.querySelector('#product-search')?.value||'').toLowerCase().trim(),t=panel.querySelector('#product-type-filter')?.value||'',c=panel.querySelector('#product-config-filter')?.value||'';return (r.dataset.productRow||'').includes(q)&&(!t||r.dataset.productType===t)&&(!c||r.dataset.productConfig===c);}
   if(tab==='stock'){const q=(panel.querySelector('#stock-search')?.value||'').toLowerCase().trim(),st=panel.querySelector('#stock-status')?.value||'';return (r.dataset.stockRow||'').includes(q)&&(!st||r.dataset.stockStatus===st);}
   if(tab==='close'){const q=(panel.querySelector('#close-search')?.value||'').toLowerCase().trim(),st=panel.querySelector('#close-filter')?.value||'';return (r.dataset.closeRow||'').includes(q)&&(!st||r.dataset.closeStatus===st);}
   return true;
  });
  const pages=Math.max(1,Math.ceil(eligible.length/size));page=Math.min(page,pages-1);
  const shown=new Set(eligible.slice(page*size,(page+1)*size));
  rows.forEach(r=>r.hidden=!shown.has(r));
  pager.querySelector('.psi-page-summary').textContent=`${eligible.length} coincidencias · ${rows.length} registros cargados`;
  pager.querySelector('.psi-page-number').textContent=`${page+1} / ${pages}`;
  pager.querySelector('.psi-page-prev').disabled=page===0;
  pager.querySelector('.psi-page-next').disabled=page>=pages-1;
 }
 pager.querySelector('.psi-page-size').onchange=e=>{size=Number(e.target.value);page=0;refresh();};
 pager.querySelector('.psi-page-prev').onclick=()=>{page--;refresh();};
 pager.querySelector('.psi-page-next').onclick=()=>{page++;refresh();};
 [search,filterSelect,...panel.querySelectorAll('#product-config-filter,#product-type-filter')].filter(Boolean).forEach(el=>{el.addEventListener('input',()=>{page=0;queueMicrotask(refresh)});el.addEventListener('change',()=>{page=0;queueMicrotask(refresh)});});
 refresh();
}

async function openLot(e){e.preventDefault();const id=openingLotId,l=data.lots.find(x=>x.id===id);if(!l||!canOpen(l)){notice='El frasco no está disponible para apertura.';openingLotId=null;render();return;}const form=e.currentTarget,openedDate=form.elements.openedDate.value,reason=form.elements.reason.value.trim(),today=day();if(!/^\d{4}-\d{2}-\d{2}$/.test(openedDate)||new Date(openedDate+'T12:00:00').toLocaleDateString('en-CA')!==openedDate){notice='Fecha de apertura inválida.';render();return;}if(openedDate>today||(l.receivedDate&&openedDate<l.receivedDate)){notice='La apertura debe ser entre la recepción del lote y hoy.';render();return;}if(openedDate<today&&!reason){notice='Indique el motivo de registro histórico.';render();return;}if(!confirm(`¿Confirma la apertura del frasco ${l.code||id} con fecha real ${openedDate}?`))return;const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const ref=doc(db,'microLots',id),event=doc(collection(db,'microMovements'));await runTransaction(db,async tx=>{const snap=await tx.get(ref);if(!snap.exists())throw Error('Frasco inexistente');const current={...snap.data()};if(!canOpen(current))throw Error('El frasco ya fue abierto o está bloqueado');if(current.receivedDate&&openedDate<current.receivedDate)throw Error('La apertura no puede preceder la recepción');const p=data.products.find(x=>x.id===current.productId);const days=Number(p?.afterOpenDays)||0;let effective=current.expiry||null;if(days){const d=new Date(openedDate+'T12:00:00');d.setDate(d.getDate()+days);const candidate=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');if(!effective||candidate<effective)effective=candidate;}tx.update(ref,{openedAt:openedDate,openedByUid:uid,openedByCode:window.__microUserCode||uid,openedRecordedAt:serverTimestamp(),openingReason:reason,effectiveExpiry:effective,updatedAt:serverTimestamp(),updatedBy:uid});tx.set(event,{lotId:id,productId:current.productId,batch:current.batch,unit:current.unit,quantity:0,kind:'APERTURA',date:openedDate,reference:reason?'Apertura física · '+reason:'Apertura física confirmada',actorUid:uid,actorCode:window.__microUserCode||uid,createdAt:serverTimestamp()});});openingLotId=null;notice='Apertura confirmada y auditada en Firebase.';}catch(err){notice='No se abrió: '+err.message;}render();}
async function saveStockEdit(e){e.preventDefault();const id=stockEditingId,f=e.target,x=Object.fromEntries(new FormData(f));if(!x.reason.trim())return;try{const ref=doc(db,'microLots',id),event=doc(collection(db,'microMovements'));await runTransaction(db,async tx=>{const snap=await tx.get(ref);if(!snap.exists())throw Error('Frasco inexistente');const l=snap.data();if(l.openedAt)throw Error('El frasco ya fue abierto');const quantity=Number(x.quantity);if(!Number.isFinite(quantity)||quantity<=0)throw Error('Cantidad inválida');if(x.expiry<day())throw Error('No se puede corregir a un vencimiento pasado');if(Number(l.quantity)!==Number(l.initialQuantity))throw Error('Ya existen consumos: no puede editar la cantidad inicial');tx.update(ref,{location:x.location.trim(),expiry:x.expiry,quantity,initialQuantity:quantity,updatedAt:serverTimestamp(),updatedBy:uid});tx.set(event,{lotId:id,productId:l.productId,batch:l.batch,unit:l.unit,quantity:0,kind:'CORRECCION',date:day(),reference:`${x.reason.trim()} | Anterior: ${l.location||'—'}, ${l.expiry||'—'}, ${l.quantity} ${l.unit}`,actorUid:uid,actorCode:window.__microUserCode||uid,createdAt:serverTimestamp()});});stockEditingId=null;notice='Corrección guardada y auditada.';}catch(err){notice='No se corrigió: '+err.message;}render();}
async function saveProduct(e){e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const x=Object.fromEntries(new FormData(f));x.name=x.name.trim();if(data.products.some(p=>p.id!==editingId&&p.name.toLowerCase()===x.name.toLowerCase()&&p.type!=='Cepa de referencia'&&x.type!=='Cepa de referencia'))throw Error('El producto ya está configurado.');if(x.type==='Cepa de referencia'){x.strainSpecies=x.strainSpecies.trim()||x.name;x.strainAtcc=x.strainAtcc.trim();if(!/^[0-9]{3,8}$/.test(x.strainAtcc))throw Error('Ingrese un ATCC válido (3 a 8 dígitos).');if(x.strainStorageMin!==''&&x.strainStorageMax!==''&&Number(x.strainStorageMin)>Number(x.strainStorageMax))throw Error('Temperatura mínima mayor que máxima.');x.strainLink=`${x.strainSpecies} · ATCC ${x.strainAtcc}`;if(data.products.some(p=>p.id!==editingId&&p.type==='Cepa de referencia'&&p.strainAtcc===x.strainAtcc&&String(p.manufacturer||'').trim().toLowerCase()===String(x.manufacturer||'').trim().toLowerCase()&&String(p.reference||'').trim().toLowerCase()===String(x.reference||'').trim().toLowerCase()))throw Error('Ya existe este ATCC con el mismo fabricante y referencia comercial.');}else{for(const key of ['strainSpecies','strainAtcc','strainWdcm','strainCollectionCode','strainPresentation','strainConcentration','strainStorageMin','strainStorageMax'])delete x[key];}if(x.type==='Cepa de referencia'&&x.mediaLink)throw Error('Una cepa no puede vincularse como medio.');if(x.type==='Medio de cultivo deshidratado'&&x.strainLink)throw Error('Un medio no puede vincularse como cepa.');if(x.afterOpenDays&&!x.criteria.trim())throw Error('Documente el respaldo de la vida útil postapertura.');x.minimum=Number(x.minimum)||0;x.afterOpenDays=x.afterOpenDays?Number(x.afterOpenDays):null;const payload={...x,updatedBy:uid,updatedAt:serverTimestamp()};if(editingId){const old=data.products.find(p=>p.id===editingId);if(!old)throw Error('Producto no encontrado');const before={...old};delete before.id;const history=Array.isArray(old.changeHistory)?old.changeHistory:[];payload.changeHistory=[...history.slice(-29),{at:new Date().toISOString(),uid,before}];await updateDoc(doc(db,'microProducts',editingId),payload);notice='Cambios guardados y auditados en Firebase.';editingId=null;}else{await addDoc(collection(db,'microProducts'),{...payload,createdBy:uid,createdAt:serverTimestamp(),changeHistory:[]});notice='Producto confirmado en Firebase.';}clearDraft();}catch(err){notice='No se guardó: '+err.message}render()}
let savingLot=false;
const eligibleParents=()=>data.lots.filter(l=>l.productId&&l.batch&&l.status!=='RECHAZADO');
async function saveLot(e){
 e.preventDefault();if(savingLot)return;
 const f=e.target,b=f.querySelector('button');savingLot=true;b.disabled=true;
 try{
  const x=Object.fromEntries(new FormData(f));
  const bottle=x.entryMode==='BOTTLE';
  const parent=bottle?data.lots.find(l=>l.id===x.parentLotId):null;
  if(bottle&&!parent)throw Error('Seleccione un lote existente');
  if(bottle){for(const key of ['productId','batch','supplier','expiry','coaStatus'])x[key]=parent[key];}
  const p=data.products.find(p=>p.id===x.productId);
  if(!p)throw Error('Seleccione un producto');
  delete x.code;delete x.entryMode;delete x.parentLotId;x.batch=x.batch.trim();
  if(!x.batch)throw Error('Ingrese el lote del fabricante');
  const qty=Number(x.quantity);
  if(!Number.isFinite(qty)||qty<=0)throw Error('Cantidad inválida');
  if(x.receivedDate>day())throw Error('La fecha de recepción no puede ser futura');
  const expired=x.expiry<day(),requiresCoa=p.requiresCoa!=='NO';
  if(x.coaStatus==='NO_APLICA'&&requiresCoa)throw Error('El catálogo exige CoA: no se puede marcar No aplica');
  const failures=x.packageStatus==='NO_CONFORME'||x.labelStatus==='NO_CONFORME';
  const status=x.evaluation==='RECHAZADO'||failures?'RECHAZADO':x.evaluation==='CONFORME'&&!expired&&(!requiresCoa||x.coaStatus==='VERIFICADO')?'LIBERADO':'CUARENTENA';
  if(x.evaluation==='CONFORME'&&status!=='LIBERADO')throw Error('No se puede liberar: vencimiento o CoA pendiente. Registre como pendiente/cuarentena');
  const year=new Date().getFullYear(),counterRef=doc(db,'microCounters',`lots-${year}`);
  const code=await runTransaction(db,async tx=>{
   const counter=await tx.get(counterRef);
   const next=(counter.exists()?Number(counter.data().lastNumber)||0:0)+1;
   if(next>999999)throw Error('Límite de numeración anual alcanzado');
   const assigned=`R-${year}-${String(next).padStart(3,'0')}`;
   const lotRef=doc(db,'microLots',assigned);
   const parentSnap=bottle?await tx.get(doc(db,'microLots',parent.id)):null;
   if(bottle&&(!parentSnap.exists()||parentSnap.data().productId!==x.productId||parentSnap.data().batch!==x.batch))throw Error('El lote de origen cambió; actualice la pantalla');
   const existing=await tx.get(lotRef);
   if(existing.exists())throw Error('El código ya existe. Verifique el contador antes de continuar');
   tx.set(counterRef,{lastNumber:next,year,updatedBy:uid,updatedAt:serverTimestamp()});
   tx.set(lotRef,{...x,code:assigned,parentLotCode:bottle?(parent.parentLotCode||parent.code||parent.id):null,entryType:bottle?'FRASCO_ADICIONAL':'LOTE_COMERCIAL',status,reviewerUid:uid,reviewer:window.__microUserCode||uid,quantity:qty,initialQuantity:qty,unit:p.unit,updatedBy:uid,updatedAt:serverTimestamp(),createdAt:serverTimestamp()});
   return assigned;
  });
  notice=`${bottle?'Frasco adicional':'Lote'} ${code} registrado y confirmado en Firebase con estado ${status}.`;
 }catch(err){notice='No se guardó: '+err.message}
 finally{savingLot=false;render()}
}
async function saveDisposal(e){
 e.preventDefault();const id=closeSelectedId, f=e.target, button=f.querySelector('button');if(!id||!canWrite)return;
 const x=Object.fromEntries(new FormData(f));if(!x.method?.trim()||!x.notes?.trim())return;
 if(!confirm(`¿Confirma la disposición definitiva de ${id}? Esta operación no se puede revertir desde la interfaz.`))return;
 button.disabled=true;
 try{const ref=doc(db,'microLots',id),movement=doc(collection(db,'microMovements'));
 await runTransaction(db,async tx=>{const snap=await tx.get(ref);if(!snap.exists())throw Error('Frasco inexistente');const l=snap.data();if(l.status==='DESCARTADO')throw Error('Disposición ya registrada');const qty=Number(l.quantity);if(!Number.isFinite(qty)||qty<0)throw Error('Saldo inválido');tx.update(ref,{quantity:0,status:'DESCARTADO',updatedBy:uid,updatedAt:serverTimestamp()});tx.set(movement,{lotId:id,productId:l.productId,batch:l.batch,unit:l.unit,quantity:qty,kind:'DESCARTE',destination:x.method.trim(),reference:x.reason,notes:x.notes.trim(),date:day(),actorUid:uid,actorCode:window.__microUserCode||uid,createdAt:serverTimestamp()});});
 closeSelectedId='';notice='Disposición confirmada y registrada en Firebase.';
 }catch(err){notice='No se registró la disposición: '+err.message;}render();
}
async function saveUse(e){e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const x=Object.fromEntries(new FormData(f)),qty=Number(x.quantity),lot=data.lots.find(l=>l.id===x.lotId);if(!lot||!Number.isFinite(qty)||qty<=0)throw Error('Lote o cantidad inválida.');const movement=doc(collection(db,'microMovements'));await runTransaction(db,async tx=>{const ref=doc(db,'microLots',x.lotId),snap=await tx.get(ref);if(!snap.exists())throw Error('Lote inexistente');const l=snap.data();if(!['APTO','POR VENCER'].includes(state(l))||!l.openedAt)throw Error('El frasco debe estar abierto y vigente para consumir');if(qty>Number(l.quantity))throw Error('Existencia insuficiente');if(!x.reference?.trim())throw Error('Ingrese una referencia de trazabilidad');tx.update(ref,{quantity:Math.round((Number(l.quantity)-qty)*1e6)/1e6,updatedBy:uid,updatedAt:serverTimestamp()});tx.set(movement,{lotId:x.lotId,productId:l.productId,batch:l.batch,unit:l.unit,quantity:qty,kind:'CONSUMO',destination:x.destination,reference:x.reference.trim(),notes:x.notes||'',date:day(),actorUid:uid,actorCode:window.__microUserCode||uid,createdAt:serverTimestamp()})});notice='Consumo confirmado y descontado en Firebase.';}catch(err){notice='No se descontó: '+err.message}render()}
export function renderProducts(node,user,profile){stopProducts();host=node;uid=user.uid;window.__microUserCode=profile.userCode||user.email;canWrite=['ADMIN','JEFE'].includes(profile.role)||profile.permissions?.products==='WRITE';data={products:[],lots:[],moves:[]};tab='catalog';editingId=null;notice='';render();[['products','microProducts'],['lots','microLots'],['moves','microMovements']].forEach(([key,path])=>{unsubs.push(onSnapshot(query(collection(db,path)),snap=>{data[key]=snap.docs.map(d=>({id:d.id,...d.data()}));if(key==='moves')data[key].sort((a,b)=>(b.date||'').localeCompare(a.date||''));render()},err=>{notice='Error de lectura de '+path+': '+err.message;render()}))})}
